{"implementation":"def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build union-find structure
    parent = {}
    rank = {}
    def make_set(v):
        parent[v] = v
        rank[v] = 0
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]  # path compression
            v = parent[v]
        return v
    def union(v1, v2):
        r1 = find(v1)
        r2 = find(v2)
        if r1 == r2:
            return False
        if rank[r1] < rank[r2]:
            parent[r1] = r2
        elif rank[r1] > rank[r2]:
            parent[r2] = r1
        else:
            parent[r2] = r1
            rank[r1] += 1
        return True

    for v in nodes:
        make_set(v)

    # Build mutual-reachability edges, canonicalise node order
    edges = []
    for a, b, d in distances:
        u, v = (a, b) if a < b else (b, a)
        core_u = core_distance[u]
        core_v = core_distance[v]
        w = max(core_u, core_v, d)
        edges.append((w, u, v))

    # Sort deterministic: weight then node1 then node2
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected or insufficient edges to form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
"}
